// Changes: Behaviour of the confirm/prompt queue – one dialog at a time, answers go to the right caller.

import { describe, expect, it, vi } from 'vitest'
import { DialogQueue, confirmResult, promptResult } from './dialogQueue'

describe('dialog queue', () => {
  it('shows one request at a time and resolves each caller with its own answer', async () => {
    const q = new DialogQueue<string, boolean>()
    const first = q.request('a')
    const second = q.request('b')
    expect(q.current()?.request).toBe('a')

    q.settle(q.current()!.id, true)
    expect(q.current()?.request).toBe('b')
    q.settle(q.current()!.id, false)
    expect(q.current()).toBeNull()

    await expect(first).resolves.toBe(true)
    await expect(second).resolves.toBe(false)
  })

  it('ignores a second answer for an already settled request', async () => {
    const q = new DialogQueue<string, boolean>()
    const first = q.request('a')
    const id = q.current()!.id
    const second = q.request('b')
    q.settle(id, true)
    q.settle(id, false)
    expect(q.current()?.request).toBe('b')
    await expect(first).resolves.toBe(true)
    q.settle(q.current()!.id, true)
    await expect(second).resolves.toBe(true)
  })

  it('notifies subscribers when the visible request changes', () => {
    const q = new DialogQueue<string, boolean>()
    const fn = vi.fn()
    const off = q.subscribe(fn)
    void q.request('a')
    q.settle(q.current()!.id, true)
    off()
    void q.request('b')
    expect(fn).toHaveBeenCalledTimes(2)
  })

  it('returns the same snapshot until something changes', () => {
    const q = new DialogQueue<string, boolean>()
    void q.request('a')
    expect(q.current()).toBe(q.current())
  })
})

describe('dialog results', () => {
  it('confirms only through the confirm button (Esc and Cancel give false)', () => {
    expect(confirmResult('confirm')).toBe(true)
    expect(confirmResult('cancel')).toBe(false)
    expect(confirmResult('')).toBe(false)
  })

  it('returns the trimmed prompt text, or null when cancelled or blank', () => {
    expect(promptResult('confirm', '  Nový názov ')).toBe('Nový názov')
    expect(promptResult('confirm', '   ')).toBeNull()
    expect(promptResult('cancel', 'Nový názov')).toBeNull()
    expect(promptResult('', 'Nový názov')).toBeNull()
  })
})
